        # returns (num, den, rad) where sval = (num/den)*sqrt(rad), with sqrt(1)=1
        if k == 4:
            return (1, 2, 1)  # 1/2 * sqrt(1)
        else:
            return (1, 4, 3)  # 1/4 * sqrt(3)

    def sval_numeric(k):
        return 0.5 if k == 4 else math.sqrt(3)/4.0

    def A_numeric(k):
        return math.pi / k - sval_numeric(k)

    # Compute the three regions numerically to confirm ordering
    S = A_numeric(k2)
    M = A_numeric(k1) - A_numeric(k2)
    L = math.pi - A_numeric(k1)

    # Enforce the nontrivial ordering (largest is L, smallest is S) to avoid degenerate/easier cases
    if not (S < M and L > M and L > S):
        # This instance would break the canonical one-radical denominator or the intended difficulty
        return (False, None)

    # Build canonical integer coefficients for (aπ + b√c)/(dπ - e√f)
