    # Denominator corresponds to S = A(k2) = π*(1/k2) - sval(k2)
    LCM = lcm(lcm(4, k1), k2)  # clears all denominators (k1, k2, and 2 or 4)

    # Numerator coefficients
    a = LCM * (k1 - 1) // k1
    numN, denN, radN = sval_numden_and_rad(k1)
    b = LCM * numN // denN
    c = radN

    # Denominator coefficients
    d = LCM // k2
    numD, denD, radD = sval_numden_and_rad(k2)
    e = LCM * numD // denD
    f = radD

    # Normalize by gcd across (a,b,d,e)
    g = gcd(gcd(a, b), gcd(d, e))
    a //= g
    b //= g
    d //= g
    e //= g

    # Positivity checks per statement
    if not (a > 0 and b > 0 and d > 0 and e > 0):
        return (False, None)
    # Squarefree c and f (here they are 1 or 3)
    if c not in (1,3) or f not in (1,3):
        return (False, None)

