    RN = a*math.pi + b*math.sqrt(c)
    RD = d*math.pi - e*math.sqrt(f)
    if RD <= 0:
        return (False, None)
    ratio_expr = RN / RD
    ratio_true = L / S
    if not (abs(ratio_expr - ratio_true) <= 1e-9):
        return (False, None)

    # Compute the requested remainder
    prod = (a * b * c * d * e * f) % modulus
    return (True, prod)


